set-variable.value:
@{
      if (!string.Equals(context.Request.Method, "POST", StringComparison.OrdinalIgnoreCase) || context.Request.Body == null)
      {
        return false;
      }
      try
      {
        var body = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
        return string.Equals((string)body["method"], "tools/list", StringComparison.Ordinal);
      }
      catch
      {
        return false;
      }
    }

@{
          var original = context.Variables.GetValueOrDefault<string>("originalToolsListBody", "");
          var contentType = context.Response.Headers.GetValueOrDefault("Content-Type", "");
          var payload = original;

          if (contentType.IndexOf("text/event-stream", StringComparison.OrdinalIgnoreCase) >= 0)
          {
            var normalized = original.Replace("\r\n", "\n").Trim();
            var eventEnd = normalized.IndexOf("\n\n", StringComparison.Ordinal);
            var eventText = eventEnd >= 0 ? normalized.Substring(0, eventEnd) : normalized;
            var remainder = eventEnd >= 0 ? normalized.Substring(eventEnd + 2).Trim() : "";
            if (!string.IsNullOrEmpty(remainder))
            {
              return original;
            }

            var data = "";
            var offset = 0;
            while (offset <= eventText.Length)
            {
              var lineEnd = eventText.IndexOf('\n', offset);
              var line = lineEnd >= 0 ? eventText.Substring(offset, lineEnd - offset) : eventText.Substring(offset);
              if (line.StartsWith("data:", StringComparison.Ordinal))
              {
                if (data.Length > 0)
                {
                  data += "\n";
                }
                data += line.Substring(5).TrimStart();
              }
              if (lineEnd < 0)
              {
                break;
              }
              offset = lineEnd + 1;
            }

            if (string.IsNullOrWhiteSpace(data))
            {
              return original;
            }
            payload = data;
          }

          try
          {
            var document = Newtonsoft.Json.Linq.JObject.Parse(payload);
            var tools = document["result"]?["tools"] as Newtonsoft.Json.Linq.JArray;
            if (tools == null)
            {
              return original;
            }

            foreach (var token in tools)
            {
              var tool = token as Newtonsoft.Json.Linq.JObject;
              if (tool == null)
              {
                continue;
              }

              var outputSchema = tool["outputSchema"];
              if (outputSchema != null && outputSchema.Type == Newtonsoft.Json.Linq.JTokenType.Boolean)
              {
                tool.Remove("outputSchema");
                continue;
              }

              var outputObject = outputSchema as Newtonsoft.Json.Linq.JObject;
              var properties = outputObject?["properties"] as Newtonsoft.Json.Linq.JObject;
              var result = properties?["result"];
              if (result != null && result.Type == Newtonsoft.Json.Linq.JTokenType.Boolean && (bool)result)
              {
                properties["result"] = new Newtonsoft.Json.Linq.JObject();
              }
            }
            return document.ToString(Newtonsoft.Json.Formatting.None);
          }
          catch
          {
            return original;
          }
        }
